def flattened_interquartile_range(nested):
    data = sorted(x for row in nested for x in row)
    n = len(data)

    def quantile(q):
        pos = q * (n - 1)
        lo = int(pos)
        hi = min(lo + 1, n - 1)
        frac = pos - lo
        return data[lo] + (data[hi] - data[lo]) * frac

    return float(quantile(0.75) - quantile(0.25))

