import statistics

def paired_word_length_t_statistic(text1, text2):
    a = [len(w) for w in re.findall(r'\w+', text1)]
    b = [len(w) for w in re.findall(r'\w+', text2)]
    if len(a) != len(b):
        raise ValueError('texts have different numbers of words')
    d = [x - y for x, y in zip(a, b)]
    return statistics.mean(d) / (statistics.stdev(d) / math.sqrt(len(d)))

