from collections import defaultdict

def scale_by_group_with_histogram(rows):
    if not rows:
        raise ValueError("rows must not be empty")
    groups = defaultdict(list)
    for gid, age, income in rows:
        groups[gid].append((age, income))
    bounds = {}
    for gid, vals in groups.items():
        ages = [a for a, _ in vals]
        incs = [i for _, i in vals]
        bounds[gid] = (min(ages), max(ages), min(incs), max(incs))

    def scale(v, lo, hi):
        return (v - lo) / (hi - lo) if hi > lo else 0.0

    scaled = []
    for gid, age, income in rows:
        alo, ahi, ilo, ihi = bounds[gid]
        scaled.append((gid, scale(age, alo, ahi), scale(income, ilo, ihi)))

    incomes = [s[2] for s in scaled]
    lo, hi = min(incomes), max(incomes)
    if hi == lo:
        lo -= 0.5
        hi += 0.5
    counts = [0] * 10
    for v in incomes:
        idx = int((v - lo) / (hi - lo) * 10)
        if idx >= 10:
            idx = 9
        counts[idx] += 1
    return scaled, counts

from html.parser import HTMLParser


class _TableParser(HTMLParser):
    def __init__(self, table_id):
        super().__init__()
        self.table_id = table_id
        self.found = False
        self.done = False
        self.depth = 0
        self.rows = []
        self.cell = None

    def _close_cell(self):
        if self.cell is not None:
            self.rows[-1].append(" ".join("".join(self.cell).split()))
            self.cell = None

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if tag == "table":
            if self.depth:
                self.depth += 1
            elif dict(attrs).get("id") == self.table_id:
                self.found = True
                self.depth = 1
            return
        if self.depth != 1:
            return
        if tag == "tr":
            self._close_cell()
            self.rows.append([])
        elif tag in ("td", "th"):
            if not self.rows:
                self.rows.append([])
            self._close_cell()
            self.cell = []

    def handle_endtag(self, tag):
        if self.done or not self.depth:
            return
        if tag == "table":
            self.depth -= 1
            if self.depth == 0:
                self._close_cell()
                self.done = True
            return
        if self.depth == 1 and tag in ("td", "th", "tr"):
            self._close_cell()

    def handle_data(self, data):
        if self.cell is not None:
            self.cell.append(data)


def html_table_to_records(html, table_id):
    parser = _TableParser(table_id)
    parser.feed(html)
    parser.close()
    if not parser.found:
        raise ValueError("Table with the specified ID not found.")
    rows = parser.rows
    if not rows:
        return []
    header = rows[0]
    return [dict(zip(header, row)) for row in rows[1:]]

import math
from itertools import accumulate


def normalized_cumulative_sums(data):
    if not data or any(len(v) == 0 for v in data.values()):
        raise ValueError("Table is empty")
    for values in data.values():
        for v in values:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                raise TypeError("Non-numeric value found")
            if isinstance(v, float) and math.isnan(v):
                raise ValueError("NaN value found")
    result = {}
    for name, values in data.items():
        cs = list(accumulate(values))
        lo, hi = min(cs), max(cs)
        rng = hi - lo
        result[name] = [float((c - lo) / rng) if rng else 0.0 for c in cs]
    return result

