import numpy as np
import pandas as pd
from sklearn.preprocessing import MinMaxScaler


def normalized_cumulative_sums(data):
    df = pd.DataFrame(data)
    if df.empty:
        raise ValueError("Table is empty")
    if df.select_dtypes(include=np.number).shape[1] != df.shape[1]:
        raise TypeError("Non-numeric data found")
    if df.isnull().values.any():
        raise ValueError("NaN values found")
    df_cumsum = df.cumsum()
    scaled = MinMaxScaler().fit_transform(df_cumsum)
    out = pd.DataFrame(scaled, columns=df.columns)
    return {col: [float(x) for x in out[col].tolist()] for col in df.columns}
